<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\Accessor\TrustedClientRequirePkceAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TrustedClientRequirePkceAccessor trait.
 *
 * Covers null default, string/VO assignment via withRequirePkce,
 * getRequirePkce/requirePkce accessors, and isRequirePkceChanged with/without original.
 */
class TrustedClientRequirePkceAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withRequirePkce creates a new instance with the RequirePkce set
     * from a string value, and getRequirePkce returns the primitive string.
     */
    public function testWithRequirePkceFromString(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientRequirePkceAccessorUnitTest();

        // Act
        $result = $holder->withRequirePkce(true);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(true, $result->isRequirePkce());
    }
    /**
     * Asserts that withrequirePkce has access to the value object
     * from a string value, and getRequirePkce returns the primitive string.
     */
    public function testWithRequirePkceFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientRequirePkceAccessorUnitTest();

        // Act
        $result = $holder->withRequirePkce(true);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(true, $result->requirePkce()->value());
    }
    public function testChangedRequirePkce(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientRequirePkceAccessorUnitTest()->withRequirePkce(true);
        $original = $holder->withRequirePkce(true);
        $same = $holder->withRequirePkce(true);
        $modified = $holder->withRequirePkce(false);

        // Act
        $withSame = $original->isRequirePkceChanged($same);
        $withDiferent = $original->isRequirePkceChanged($modified);

        // Assert
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTrustedClientRequirePkceAccessorUnitTest
{
    use TrustedClientRequirePkceAccessor;
}
